-- Slug üret (yeni satırlar) — ÇAKIŞMAYA DAYANIKLI.
-- 1) Çakışmayanlara temiz slug (mevcut slug'larla ve kendi aralarında benzersiz).
update public.exercises e
set slug = x.cand
from (
  select id,
         trim(both '-' from regexp_replace(lower(unaccent(name)), '[^a-z0-9]+', '-', 'g')) as cand,
         row_number() over (
           partition by trim(both '-' from regexp_replace(lower(unaccent(name)), '[^a-z0-9]+', '-', 'g'))
           order by id
         ) as rn
  from public.exercises
  where slug is null or slug = ''
) x
where e.id = x.id
  and x.rn = 1
  and not exists (select 1 from public.exercises o where o.slug = x.cand);

-- 2) Kalan (çakışan) satırlara benzersiz sonek ekle.
update public.exercises
set slug = trim(both '-' from regexp_replace(lower(unaccent(name)), '[^a-z0-9]+', '-', 'g'))
           || '-' || substr(md5(id::text), 1, 6)
where slug is null or slug = '';

